import{connectResultsBoard}from'./results-board-bridge.js';
import{fetchCohortJSON}from'./current-cohort-loader.js';import{applyModelContext056}from'./open-explorer-056.js';
import{applyExplorerReviews053}from'./explorer-053-replay.js';
import {handleExplorerAction,explorerActions,explorerFilterRoute} from './open-explorer-flow-087.js';
import {resolveExplorerRoute} from './open-explorer.js';
import {applyBroadFollowups052} from './broad-followups-052-replay.js';
import {answerBroadQuestion,beginBroadRound,broadRoundQuestion} from './broad-exploration.js';
import {applyCoverageExploration} from './coverage-050-replay.js';
import{cohort049FinalState}from'./cohort-049-audit.js';
import{newCohortLabels}from'./cohort-049-meta.js';
import {updateExpandedInterest,expandedInterestState} from './expanded-interest.js';
import {degreeControl} from './degree-inventory-controls.js';
import {offerFollowupPrompts} from './confirmation-offer-review.js';
import {professionConfirmationState} from './profession-confirmation.js';
import {professionReplayState} from './profession-replay.js';
import {updateCareerCheck,finishCareerCheckQuestion,careerCheckSpec} from './career-check-questions.js';
import {studentModelState,studentModelScreen} from './student-model-view.js';
import {makeJourneyPlan} from './profile-journey.js';
import {occupationById} from './occupation-data.js';
import {applyGuidePay} from './guide-state.js';
import {careerTitle} from './career-presentation.js';
const params=new URL(location.href).searchParams,id=params.get('case')||'life-013',main=document.querySelector('#main'),label=document.querySelector('#model-label'),status=document.querySelector('#preview-status');
let state=null,auth=null,stopAuthWatch=null,degreeView={education:['college','graduate'].includes(params.get('degreeEducation'))?params.get('degreeEducation'):''};
const allowed=new Set([...explorerActions,'broad-start','broad-reflect','expanded-interest-answer','degree-clear','degree-all','journey-plan','guide-use-career','guide-primary','guide-save-alternative','guide-remove-alternative','guide-keep-salary','activity-feedback','print','career-check-toggle','career-check-next','career-check-skip','career-check-unfamiliar','career-check-not-interested']);
const route=()=>{const r=location.hash.replace(/^#\/?/,'')||'journey/explore';return state?(resolveExplorerRoute(state,r)||r):r;};
function render(){if(!state)return;main.innerHTML=studentModelScreen(state,route(),degreeView);connectResultsBoard(state,{preview:true,navigate:go,route:route()});document.querySelector('#sample-choice').textContent=state.guide.primaryCareer?'Example choice: '+careerTitle(occupationById(state.guide.primaryCareer)):'Compare the career results first.';for(const b of main.querySelectorAll('button[data-action]'))if(!allowed.has(b.dataset.action)){b.disabled=true;b.title='Read-only example';}for(const el of main.querySelectorAll('input,select,textarea'))if(!el.dataset.actionCheck&&!el.dataset.planAction&&!el.id.startsWith('degree-')&&el.name!=='broad-choice'&&el.name!=='topic056'&&!el.closest('#explorer-filters,#explorer-answer,#automatic-followup-answer'))el.disabled=true;document.title=state.profile.nickname+' · Student view · Fieldguide';for(const [id,r] of [['plan-tab','plan'],['matches-tab','journey/professions']]){const el=document.getElementById(id);if(route()===r)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');}}
function go(r){if(route()===r)render();else location.hash='/'+r;}
function choose(careerId){if(!occupationById(careerId)||!makeJourneyPlan(state,careerId))return false;const u=new URL(location.href);u.searchParams.set('career',careerId);history.replaceState(null,'',u);return true;}
async function load(){try{
 let c;if(/^private-\d{3}$/.test(id)){const m=await import('./firebase-client.js?v=0.47.0');auth=m.authClient;const session=await auth.getSession();if(!session.data?.user){label.textContent='Private model';status.textContent='Sign in with the owner account to view this example.';document.querySelector('#preview-signin').hidden=false;return;}c=(await m.getPrivateReviewCases()).find(c=>c.id===id);stopAuthWatch?.();const owner=session.data.user.id;stopAuthWatch=auth.watch(next=>{if(next?.id!==owner){state=null;main.replaceChildren();label.textContent='Private model';document.querySelector('#sample-choice').textContent='';status.textContent='Sign in with the owner account to view this example.';document.querySelector('#preview-signin').hidden=false;}});}else{const index=await fetch('./developer/model-lab-data.json').then(r=>r.json());if(!index.rows.some(c=>c.id===id))throw Error('Choose a model from the library.');c=await fetchCohortJSON('./developer/lives/'+encodeURIComponent(id)+(/^scale056-/.test(id)?'.json.gz':'.json'));}
 if(!c)throw Error('This model is available only to its owner.');const final=params.get('replay')==='final',pre047=params.get('replay')==='pre047',prior=params.get('replay')==='prior',core042=params.get('replay')==='core042';if(c.cohort056){c={...c,experimentState:structuredClone(c.experimentState)};}else if(c.cohort049){c={...c,experimentState:final?cohort049FinalState(c):structuredClone(c.experimentState)};delete c.experimentState._historicalMatchRules;}else if(final||pre047||prior||core042){let replay=c.professionReplay;if(!replay&&!id.startsWith('private-')){const response=await fetch('./developer/profession-replay-answers.json',{cache:'no-store'});if(!response.ok)throw Error('The comparison replay could not load.');replay=(await response.json()).rows.find(r=>r.id===id);}if(!replay)throw Error('No comparison replay is available for this model.');c={...c,experimentState:professionReplayState(c,replay)};let core=c.professionConfirmation;if(!core&&!id.startsWith('private-')){const response=await fetch('./developer/profession-confirmation-answers.json',{cache:'no-store'});if(!response.ok)throw Error('Core-work replay could not load.');core=(await response.json()).rows.find(r=>r.id===id);}c={...c,experimentState:prior?{...c.experimentState,_historicalMatchRules:true}:professionConfirmationState(c.experimentState,core)};if(final||pre047){let interest=c.professionInterest;if(!interest&&!id.startsWith('private-')){const response=await fetch('./developer/profession-interest-answers.json',{cache:'no-store'});if(!response.ok)throw Error('The defining-work replay could not load.');interest=(await response.json()).rows.find(r=>r.id===id);}if(!interest)throw Error('No defining-work replay is available for this model.');c={...c,experimentState:professionConfirmationState(c.experimentState,interest)};}}if(final&&!c.cohort049&&!c.cohort056){let expanded=c.expandedInterest;if(!expanded&&!id.startsWith('private-')){expanded=(await fetchCohortJSON('./developer/expanded-degree-answers.json.gz')).rows.find(r=>r.id===id);}if(!expanded)throw Error('No expanded-interest replay is available for this model.');c={...c,experimentState:expandedInterestState(c.experimentState,expanded)};}if(final)c={...c,experimentState:applyCoverageExploration(c.experimentState,c.id)};if(final)c={...c,experimentState:applyBroadFollowups052(c.experimentState,c.id)};if(final)c={...c,experimentState:applyModelContext056(applyExplorerReviews053(c.experimentState,c.id),c)};state=studentModelState(c,params.get('career')||'');if(!c.cohort049&&!final&&!pre047&&!core042)state._historicalMatchRules=true;if(!c.cohort049&&core042)state._coreWorkVersion='0.42.0';if(!c.cohort049&&core042&&params.get('followup'))state.modelFollowUpQuestions=offerFollowupPrompts(id,params.get('followup'),c.confirmationOfferReview);label.textContent='Fictional example · '+c.biography.name+(c.cohort049?' · '+(newCohortLabels[c.phase]||c.phase)+(c.cohort049.kind==='diagnostic'?' · Diagnostic variant':''):'' );document.querySelector('#review-link').href='./developer/model-lab.html?case='+encodeURIComponent(id);document.querySelector('#preview-signin').hidden=true;status.textContent=(c.cohort049?(final?'Saved 0.56 answers · current inventory':'Initial 0.49 · current rules before defining-work comparisons'):prior?'After 0.41 comparisons · before core work checks':core042?'Historical 0.42 core-work checks':pre047?'Before expanded professions · 0.46':final?'Saved 0.56 answers · current inventory':'Before profession comparisons')+(c.cohort049?.intervention?' · '+c.cohort049.intervention:'')+' · changes stay in this preview';if(c.cohort049?.baseId){const parent=document.createElement('a');parent.href='./student-view.html?case='+encodeURIComponent(c.cohort049.baseId)+'&replay='+(final?'final':'first')+'#/journey/professions';parent.textContent=' · Parent profile: '+c.cohort049.baseId+' →';status.append(parent);}if(c.cohort056)status.textContent='Saved 0.56 structured fixture · current inventory · '+(c.phase==='holdout056'?'holdout, fixed-rule evaluation only':'development')+' · changes stay in this preview';render();
 }catch(e){label.textContent='Student example';status.textContent=e.message||'The example could not load. Open it from the model library.';}}
document.querySelector('#preview-signin').addEventListener('click',async()=>{try{await auth.googleSignIn();await load();}catch{status.textContent='Sign-in did not finish. Please try again.';}});
main.addEventListener('click',e=>{const scroll=e.target.closest('[data-scroll-to]');if(scroll){e.preventDefault();(()=>{const target=document.getElementById(scroll.dataset.scrollTo);for(let node=target;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;return target;})()?.scrollIntoView({block:'start',behavior:'smooth'});return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,careerId=b.dataset.id;
 if(handleExplorerAction(state,b,{route,go,render,root:main}))return;
 if(['career-check-toggle','career-check-next','career-check-skip','career-check-unfamiliar','career-check-not-interested'].includes(a)){
  delete state._historicalMatchRules;const target=b.dataset.career,spec=careerCheckSpec(target),q=spec?.questions.find(q=>q.id===b.dataset.question);if(!q||route().split('/')[2]!==target)return;
  if(a==='career-check-toggle'){updateCareerCheck(state,{careerId:target,questionId:q.id,optionId:careerId});render();return;}
  if(a!=='career-check-next')updateCareerCheck(state,{careerId:target,questionId:q.id,skip:true,feedback:a==='career-check-unfamiliar'?'unfamiliar':a==='career-check-not-interested'?'not-interested':'unsure'});else finishCareerCheckQuestion(state,target,q.id);
  const i=spec.questions.indexOf(q);go('journey/check-career/'+target+'/'+(i+1<spec.questions.length?i+1:'summary'));return;
 }
 if(a==='broad-start'){beginBroadRound(state);go('journey/discover/reflect/0');return;}
 if(a==='broad-reflect'){
  if(!state.profileJourney.broadRound)beginBroadRound(state);const pending=broadRoundQuestion(state);if(!pending||pending.careerId!==b.dataset.career||pending.questionId!==b.dataset.question){render();return;}
  const selected=[...main.querySelectorAll('#broad-reflection input[name="broad-choice"]:checked')].map(el=>el.value);
  if(!answerBroadQuestion(state,{careerId:b.dataset.career,questionId:b.dataset.question,response:b.dataset.response,selected})){document.getElementById('broad-answer-error').textContent='Choose an example that appeals, or choose one of the other responses.';return;}
  state.profileJourney.broadRound.cursor=pending.index+1;go(broadRoundQuestion(state)?'journey/discover/reflect/'+(Number(b.dataset.turn)+1):'journey/discover');return;
 }
 if(a==='expanded-interest-answer'){if(updateExpandedInterest(state,careerId,b.dataset.question,b.dataset.value))render();return;}
 if(a==='degree-clear'){degreeView={};render();return;}
 if(a==='degree-all'){degreeView.showAll=true;render();return;}
 if(a==='print'){window.print();return;}
 if(['journey-plan','guide-use-career','guide-primary'].includes(a)){if(choose(careerId))go('plan');return;}
 if(a==='guide-keep-salary'){if(state.guide.primaryCareer!==careerId&&!choose(careerId))return;state.guide.salaryStage=b.dataset.stage;applyGuidePay(state);go('plan');return;}
 if(a==='guide-save-alternative'){state.guide.careerIds=[...new Set([...state.guide.careerIds,careerId])].slice(0,3);render();return;}
 if(a==='guide-remove-alternative'){state.guide.careerIds=state.guide.careerIds.filter(x=>x!==careerId);render();return;}
 if(a==='activity-feedback'){const step=state.actions.find(x=>x.id===careerId);if(step){step.interestFeedback=b.dataset.value;render();}}
});
main.addEventListener('change',e=>{const el=e.target;if(el.id!=='degree-search'&&degreeControl(el,degreeView)){render();return;}if(el.dataset.actionCheck){const a=state.actions.find(x=>x.id===el.dataset.actionCheck);if(a){a.done=el.checked;render();}}if(el.dataset.planAction){const a=state.actions.find(x=>x.id===el.dataset.planAction);if(a&&['notice','dueDate','support','heldInterest','energy','friction','continueDecision'].includes(el.dataset.planField))a[el.dataset.planField]=el.value;}});
main.addEventListener('input',e=>{const el=e.target;if(el.id==='degree-search'){const pos=el.selectionStart;degreeControl(el,degreeView);render();const next=document.getElementById('degree-search');next?.focus();next?.setSelectionRange(pos,pos);return;}if(el.dataset.planAction){const a=state.actions.find(x=>x.id===el.dataset.planAction);if(a&&['notice','dueDate','support','heldInterest','energy','friction','continueDecision'].includes(el.dataset.planField))a[el.dataset.planField]=el.value;}});
main.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='explorer-filters')go(explorerFilterRoute(e.target));});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
await load();
